import { Gfx, PENCIL, type Ctx, type Env, rng, displace, type P } from "./core";
import { type Film } from "./film";
import { photoFields } from "./fromPhoto";

const W = 576, H = 1024, FPS = 30, DURATION = 300;

export const drawPhoto = (ctx: Ctx, frame: number, env: Env) => {
  const g = new Gfx(ctx, env, frame, PENCIL);
  const pf = photoFields(env, "krishna");
  const r = rng(42); // Deterministic seed

  // Only draw if we haven't finished (it's a cumulative drawing!)
  // Wait, the `draw` function is called for EACH frame from scratch in Anidoodle!
  // To make a timelapse, we need to draw everything up to `frame`!
  // Frame 0 is blank. Frame `DURATION` is complete.

  ctx.setTransform(env.scale, 0, 0, env.scale, 0, 0);
  
  // Paper background
  ctx.fillStyle = "#f5f2eb"; // A warm paper color like the original blueprint
  ctx.fillRect(0, 0, W, H);

  // We want to draw marks up to the current frame.
  // Let's divide the work into "passes":
  // Pass 1: Light washes (color)
  // Pass 2: Blueprint lines and edges (ink)

  const maxStrokes = 30000;
  const strokesToDraw = Math.floor((frame / DURATION) * maxStrokes);

  // Replay exactly the same random strokes up to the current frame count
  for (let i = 0; i < strokesToDraw; i++) {
    const px = Math.floor(r() * W);
    const py = Math.floor(r() * H);
    const idx = py * W + px;

    const pr = pf.r[idx] * 255;
    const pg = pf.g[idx] * 255;
    const pb = pf.b[idx] * 255;
    const edge = pf.edge[idx];

    // Blueprint/Ink Pass (dark lines where edges are strong)
    if (i > maxStrokes * 0.6) {
      if (edge > 0.05 && r() < edge * 5) {
        // Find direction from tensor
        const J11 = pf.J11[idx], J12 = pf.J12[idx], J22 = pf.J22[idx];
        const trace = J11 + J22;
        const det = J11 * J22 - J12 * J12;
        const l1 = trace / 2 + Math.sqrt(Math.max(0, trace * trace / 4 - det));
        // Minor eigenvector (direction of the edge)
        let vx = J11 - l1, vy = J12;
        if (vx === 0 && vy === 0) { vx = J12; vy = J22 - l1; }
        const len = Math.hypot(vx, vy) || 1;
        vx /= len; vy /= len;

        const slen = 4 + r() * 15;
        ctx.beginPath();
        ctx.moveTo(px - vx * slen, py - vy * slen);
        ctx.lineTo(px + vx * slen, py + vy * slen);
        ctx.strokeStyle = `rgba(30, 40, 50, ${0.4 + r() * 0.4})`;
        ctx.lineWidth = 0.5 + r() * 1.5;
        ctx.stroke();
      }
    } else {
      // Color Wash Pass (blotches of color)
      if (r() < 0.1) {
        ctx.beginPath();
        const rad = 3 + r() * 10;
        ctx.arc(px, py, rad, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${pr},${pg},${pb}, 0.15)`;
        ctx.fill();
      }
    }
  }
};

export const photoFilm: Film = {
  meta: { title: "Krishna Blueprint", W, H, fps: FPS, bpm: 120, durationFrames: DURATION, kind: "drawing", holds: [[270, 300]] },
  assets: { images: { krishna: "data:image/jpeg;base64," } },
  shots: [{ id: "timelapse", start: 0, end: DURATION, draw: drawPhoto }],
};
